{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyOGMSQFpFqD0UnZc8ZeOs/w"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"8eK7eOIKzQz8","executionInfo":{"status":"ok","timestamp":1788433424971,"user_tz":-330,"elapsed":19,"user":{"displayName":"Gowthami Mingi","userId":"02573804330539629666"}},"outputId":"d2f2be26-d30c-4efb-a2ba-e69db74cacd6"},"outputs":[{"output_type":"stream","name":"stdout","text":["A = {1, 2, 3, 4, 5}\n","B = {4, 5, 6, 7, 8}\n","Union: {1, 2, 3, 4, 5, 6, 7, 8}\n","Union using method: {1, 2, 3, 4, 5, 6, 7, 8}\n","Intersection: {4, 5}\n","Intersection using method: {4, 5}\n","A - B: {1, 2, 3}\n","B - A: {8, 6, 7}\n","Symmetric Difference: {1, 2, 3, 6, 7, 8}\n","Using method: {1, 2, 3, 6, 7, 8}\n","After adding 10: {1, 2, 3, 4, 5, 10}\n","After adding multiple elements: {1, 2, 3, 4, 5, 10, 11, 12, 13}\n","After remove(13): {1, 2, 3, 4, 5, 10, 11, 12}\n","After discard(12): {1, 2, 3, 4, 5, 10, 11}\n","Popped element: 1\n","A after pop: {2, 3, 4, 5, 10, 11}\n","C after clear: set()\n","4 in A: True\n","100 in A: False\n","X is subset of Y: True\n","Using <= : True\n","Y is superset of X: True\n","Using >= : True\n","P and Q are disjoint: True\n","Copied set: {1, 2, 3}\n","Length of A: 6\n"]}],"source":["\n","# Creating sets\n","A = {1, 2, 3, 4, 5}\n","B = {4, 5, 6, 7, 8}\n","\n","print(\"A =\", A)\n","print(\"B =\", B)\n","\n","# 1. Union\n","print(\"Union:\", A | B)\n","print(\"Union using method:\", A.union(B))\n","\n","# 2. Intersection\n","print(\"Intersection:\", A & B)\n","print(\"Intersection using method:\", A.intersection(B))\n","\n","# 3. Difference\n","print(\"A - B:\", A - B)\n","print(\"B - A:\", B - A)\n","\n","# 4. Symmetric Difference\n","print(\"Symmetric Difference:\", A ^ B)\n","print(\"Using method:\", A.symmetric_difference(B))\n","\n","# 5. Add an element\n","A.add(10)\n","print(\"After adding 10:\", A)\n","\n","# 6. Add multiple elements\n","A.update([11, 12, 13])\n","print(\"After adding multiple elements:\", A)\n","\n","# 7. Remove an element\n","A.remove(13)\n","print(\"After remove(13):\", A)\n","\n","# 8. Discard an element\n","A.discard(12)\n","print(\"After discard(12):\", A)\n","\n","# 9. Pop an element\n","x = A.pop()\n","print(\"Popped element:\", x)\n","print(\"A after pop:\", A)\n","\n","# 10. Clear the set\n","C = {1, 2, 3}\n","C.clear()\n","print(\"C after clear:\", C)\n","\n","# 11. Check membership\n","print(\"4 in A:\", 4 in A)\n","print(\"100 in A:\", 100 in A)\n","\n","# 12. Subset\n","X = {1, 2}\n","Y = {1, 2, 3, 4}\n","\n","print(\"X is subset of Y:\", X.issubset(Y))\n","print(\"Using <= :\", X <= Y)\n","\n","# 13. Superset\n","print(\"Y is superset of X:\", Y.issuperset(X))\n","print(\"Using >= :\", Y >= X)\n","\n","# 14. Disjoint sets\n","P = {1, 2, 3}\n","Q = {4, 5, 6}\n","\n","print(\"P and Q are disjoint:\", P.isdisjoint(Q))\n","\n","# 15. Copy a set\n","S = {1, 2, 3}\n","T = S.copy()\n","print(\"Copied set:\", T)\n","\n","# 16. Set length\n","print(\"Length of A:\", len(A))\n","\n"]},{"cell_type":"code","source":["\n","# Creating sets\n","A = {1, 2, \"shiva\",3, 4, 5}\n","\n","\n","print(\"A =\", A)\n","\n"],"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"9SE7WEWT8b3A","executionInfo":{"status":"ok","timestamp":1788433565753,"user_tz":-330,"elapsed":7,"user":{"displayName":"Gowthami Mingi","userId":"02573804330539629666"}},"outputId":"6a0a11ef-d218-454a-88e4-5eec4398790d"},"execution_count":6,"outputs":[{"output_type":"stream","name":"stdout","text":["A = {1, 2, 3, 4, 5, 'shiva'}\n"]}]},{"cell_type":"code","source":[],"metadata":{"id":"WnhYhsir8YFJ"},"execution_count":null,"outputs":[]}]}